SQLite::Database db("audit.sqlite", SQLite::OPEN_READWRITE | SQLite::OPEN_CREATE);
db.exec("PRAGMA journal_mode=WAL");
SQLite::Statement ins(db, "INSERT OR IGNORE INTO msg_store VALUES (?,?,?,?)");
void tap(StoredMessage const& m) {          // delivery path: enqueue only
    if (!queue.push(m)) drops.fetch_add(1); // bounded queue, never blocks the sender
}
void writer() {                             // single owner of the connection
    while (auto m = queue.pop()) {
        SQLite::Transaction tx(db);         // RAII: rollback unless commit()
        ins.bind(1, m->id).bind(2, m->channel).bind(3, m->ts).bind(4, m->body);
        ins.exec(); ins.reset(); tx.commit();
    }
}

